pub fn parse_bool(raw: &str) -> bool {
    let s = raw.trim().to_ascii_lowercase();
    s == "true" || s == "1" || s == "yes" || s == "closed"
}

pub fn parse_wall_line(line: &str) -> Option<AdmitWall> {
    let line = line.trim();
    if line.is_empty() {
        return None;
    }
    if line.starts_with('#') || line.starts_with('@') {
        return None;
    }
    let mut id = String::new();
    let mut closed = false;
    let mut reason = String::new();
    for part in line.split('\t') {
        if let Some((k, v)) = part.split_once('=') {
            match k.trim() {
                "id" => id = v.trim().to_string(),
                "closed" => closed = parse_bool(v),
                "reason" => reason = v.trim().to_string(),
                _ => {}
            }
        }
    }
    if id.is_empty() {
        return None;
    }
    if closed {
        Some(AdmitWall::close(id, reason))
    } else {
        Some(AdmitWall::open(id))
    }
}

pub fn parse_fixture_text(text: &str) -> Vec<AdmitWall> {
    text.lines().filter_map(parse_wall_line).collect()
}

pub fn rust_eval(text: &str) -> AdmitResult {
    admit_collect_all(&parse_fixture_text(text))
}

/// Canonical collect-all text. Closed walls are already sorted by aep-admit.
pub fn format_admit_result(result: &AdmitResult) -> String {
    let mut out = String::from("allow=");
    out.push_str(if result.allow { "true" } else { "false" });
    out.push('\n');
    for wall in &result.closed {
        out.push_str("closed=");
        out.push_str(&wall.id);
        out.push('|');
        out.push_str(&wall.reason);
        out.push('\n');
    }
    out
}

pub fn default_fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../admit/crate/fixtures")
}

pub fn default_js_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../admit/lib/admit.mjs")
}

pub fn js_eval(text: &str, js: &Path, node: &str) -> anyhow::Result<String> {
    if !js.is_file() {
        return Err(anyhow!("admit.mjs missing at {}", js.display()));
    }
    let mut child = Command::new(node)
        .arg(js)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .with_context(|| format!("spawn {node} {}", js.display()))?;
    {
        let mut stdin = child
            .stdin
            .take()
            .ok_or_else(|| anyhow!("node stdin closed"))?;
        stdin.write_all(text.as_bytes())?;
    }
    let out = child
        .wait_with_output()
        .with_context(|| format!("{node} wait {}", js.display()))?;
    if !out.status.success() {
        return Err(anyhow!(
            "node admit.mjs failed status={} stderr={}",
            out.status,
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    Ok(String::from_utf8(out.stdout)?)
}

fn normalize(s: &str) -> String {
    s.replace("\r\n", "\n")
}

pub fn run_fixtures_dir(fixtures: &Path, js: &Path, node: &str) -> anyhow::Result<i32> {
    if !fixtures.is_dir() {
        return Err(anyhow!("fixtures dir missing: {}", fixtures.display()));
    }
    for name in REQUIRED_FIXTURES {
        let path = fixtures.join(name);
        if !path.is_file() {
            return Err(anyhow!("required fixture missing: {}", path.display()));
        }
        let text = fs::read_to_string(&path).with_context(|| path.display().to_string())?;
        let rust_out = format_admit_result(&rust_eval(&text));
        let js_out = js_eval(&text, js, node)?;
        if normalize(&rust_out) != normalize(&js_out) {
            eprintln!("mismatch fixture={}", name);
            eprintln!("--- rust ---");
            eprint!("{rust_out}");
            eprintln!("--- js ---");
            eprint!("{js_out}");
            return Ok(1);
        }
    }
    let a = rust_eval(&fs::read_to_string(
        fixtures.join("order-permutation-a.gaplune"),
    )?);
    let b = rust_eval(&fs::read_to_string(
        fixtures.join("order-permutation-b.gaplune"),
    )?);
    if a.closed_set_key() != b.closed_set_key() || a.allow != b.allow {
        eprintln!("mismatch order permutation closed set");
        return Ok(1);
    }
    println!(
        "aep-admit-parity ok fixtures={} rust matches js",
        REQUIRED_FIXTURES.len()
    );
    Ok(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn allow_fixture_has_empty_closed_set() {
        let text = fs::read_to_string(default_fixtures_dir().join("allow.gaplune")).unwrap();
        let result = rust_eval(&text);
        assert_eq!(result.allow, true);
        assert_eq!(result.closed.is_empty(), true);
        assert_eq!(format_admit_result(&result), "allow=true\n");
    }

    #[test]
    fn one_closed_wall_fixture() {
        let text =
            fs::read_to_string(default_fixtures_dir().join("one-closed-wall.gaplune")).unwrap();
        let result = rust_eval(&text);
        assert_eq!(result.allow, false);
        assert_eq!(result.closed.len(), 1);
        assert_eq!(result.closed[0].id, "wall.alpha");
    }

    #[test]
    fn n_closed_walls_collect_all() {
        let text =
            fs::read_to_string(default_fixtures_dir().join("n-closed-walls.gaplune")).unwrap();
        let result = rust_eval(&text);
        assert_eq!(result.allow, false);
        assert_eq!(result.closed.len(), 3);
    }

    #[test]
    fn order_permutation_same_closed_set() {
        let dir = default_fixtures_dir();
        let a = rust_eval(&fs::read_to_string(dir.join("order-permutation-a.gaplune")).unwrap());
        let b = rust_eval(&fs::read_to_string(dir.join("order-permutation-b.gaplune")).unwrap());
        assert_eq!(a.closed_set_key(), b.closed_set_key());
        assert_eq!(a.allow, b.allow);
        assert_eq!(a.closed.len(), 2);
    }

    #[test]
    fn rust_matches_js_on_shared_fixtures() {
        let code = run_fixtures_dir(&default_fixtures_dir(), &default_js_path(), "node")
            .expect("parity run");
        assert_eq!(code, 0);
    }
}
